import React, { useState } from 'react';
import axios from 'axios';

const Login = ({ setShowLoginModal, handleLoginSubmit }) => {
    const [username, setUsername] = useState('');
    const [password, setPassword] = useState('');

    return (
        <div className="login-overlay">
            <div className="login-card">
                <div className="login-banner">
                    <h1>Aura Pan Saku<br/>Educational<br/>Institute</h1>
                </div>
                <div className="login-form-container">
                    <h2>Welcome Back!</h2>
                    <form onSubmit={(e) => { e.preventDefault(); handleLoginSubmit(username, password); }}>
                        <label>User Name</label>
                        <input type="text" onChange={(e) => setUsername(e.target.value)} required />
                        <label>Password</label>
                        <input type="password" onChange={(e) => setPassword(e.target.value)} required />
                        <button type="submit" className="login-btn">Login</button>
                        <button type="button" onClick={() => setShowLoginModal(false)} style={{width:'100%', marginTop:'10px', cursor:'pointer'}}>Cancel</button>
                    </form>
                </div>
            </div>
        </div>
    );
};
export default Login;
